package com.zhibrary.book;
import com.zhibrary.user.*; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component;
@Component public class BookSeeder implements CommandLineRunner { private final BookRepository books; private final UserRepository users; public BookSeeder(BookRepository b,UserRepository u){books=b;users=u;} public void run(String...args){if(users.findByUsername("admin").isEmpty())users.save(new User("Libris","","Admin","admin@libris.local","admin","admin123",UserRole.LIBRARIAN)); if(books.count()==0){books.save(new Book("El Filibusterismo","9789712724154","Jose Rizal","Historical Fiction",1891,"/placeholder-cover.svg"));books.save(new Book("Noli Me Tangere","9789712724161","Jose Rizal","Historical Fiction",1887,"/placeholder-cover.svg"));books.save(new Book("Pride and Prejudice","9780141439518","Jane Austen","Classics",1813,"/placeholder-cover.svg"));books.save(new Book("The Great Gatsby","9780743273565","F. Scott Fitzgerald","Fiction",1925,"/placeholder-cover.svg"));books.save(new Book("Pathfit 2","9781000000002","PLM Professors","Educational",2025,"/placeholder-cover.svg"));}} }
